    } else if (operatorStrategy === 'exists' || (operatorStrategy === 'innerJoin' && operator === 'NOT IN')) {
        // For NOT IN with 'innerJoin' strategy, we use NOT EXISTS (same as 'exists' strategy)
        const existsPrefix = operator === 'NOT IN' ? 'NOT EXISTS' : 'EXISTS';
        statement = `${existsPrefix} (SELECT 1 FROM ${parameterizedParamName} AS ${tvpAlias} WHERE ${fieldName} = ${tvpAlias}.${tvpColumnName})`;
    } else {
        // Default to IN/NOT IN operator
        statement = `${fieldName} ${operator} (SELECT ${tvpColumnName} FROM ${parameterizedParamName})`;
    }

    return { paramNames: [paramName], values: [tvp], statement, alias: tvpAlias };
}

